const recDocs={};
const docRow=(name,mandatory,stage,status,by='',on='')=>({name,mandatory,stage,status,by,on});
const DOC_LIST=[['Resume / CV','Yes','Application'],['Photograph','Optional','Selection / pre-joining'],['Educational certificates','Role dependent','Pre-joining'],['Experience / relieving letter','Role dependent','Pre-joining'],['Identity proof','As required','Pre-joining'],['Address proof','As required','Pre-joining'],['PAN','As required','Pre-joining'],['Aadhaar','As required','Pre-joining'],['Offer letter','Yes, for selected','Offer'],['Signed offer / acceptance','Yes, for selected','Offer'],['Other company forms','Configurable','Pre-joining']];
function recDocsFor(candId){if(!recDocs[candId]){const apps=recApps.filter(a=>a.cand===candId);const far=Math.max(...apps.map(a=>a.stage==='Converted'?11:REC_STAGES.indexOf(a.stage)));const accepted=apps.some(a=>a.offer&&a.offer.status==='Accepted');const released=apps.some(a=>a.offer);recDocs[candId]=DOC_LIST.map(([n,m,s])=>{let status='Not yet requested',by='',on='';if(n==='Resume / CV'){status=far>=1?'Verified':'Submitted';by='Meera Demo';on=apps[0]?apps[0].date:REC_TODAY;}else if(n==='Offer letter'){status=released?'Verified':'Not applicable yet';by=released?'Meera Demo':'';}else if(n==='Signed offer / acceptance'){status=accepted?'Verified':released?'Requested':'Not applicable yet';by=accepted?'Meera Demo':'';}else if(far>=9){status=['Photograph','Other company forms'].includes(n)?'Submitted':far>=10?'Verified':['Educational certificates','Address proof'].includes(n)?'Under review':'Verified';by=status==='Verified'?'Meera Demo':'';on=status==='Verified'?'08 Sep 2026':'';}else if(far>=8){status='Requested';}return docRow(n,m,s,status,by,on);});}return recDocs[candId];}

state.rec={cand:'CND-0218',app:'APP-1041',search:'',source:'',stageF:'',jobFilter:'',ownerFilter:'',seq:100};
const recRole=()=>state.role==='hr'?'hr':state.role==='senior'?'senior':'manager';
const recUser=()=>recRole()==='hr'?'Meera Demo':recRole()==='senior'?'Kavita Demo':'Asha Demo';
const recCanPay=()=>recRole()!=='manager';
const pay=v=>recCanPay()?esc(v):'<span class="masked">Restricted</span>';
const recNow=()=>{const n=new Date();return REC_TODAY+', '+String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');};
const recDate=d=>d?d.split('-').reverse().map((x,i)=>i===1?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(x)-1]:x).join(' '):'';
const recParse=d=>Date.parse(d||'');
const recOverdue=d=>d&&recParse(d)<recParse(REC_TODAY);
const candOf=a=>recCandidates.find(c=>c.id===a.cand);
const jobOf=a=>recJobs.find(j=>j.id===a.job);
const appOf=id=>recApps.find(a=>a.id===id);
const recActive=()=>recApps.filter(a=>!a.outcome&&a.stage!=='Converted');
const recLog=(app,text)=>{app.timeline.push(ev(recNow(),text,recUser()));app.last=REC_TODAY;};
const recMove=(app,stage,note)=>{recLog(app,'Stage moved: '+app.stage+' to '+stage+(note?'. '+note:''));app.stage=stage;};
const recNextId=p=>p+'-'+(++state.rec.seq);
const stageBadge=a=>a.stage==='Converted'?badge('Converted to employee'):a.outcome?badge(a.outcome.type,a.outcome.type==='On Hold'?'amber':'red'):badge(a.stage,['Selected','Offer Accepted','Pre-Joining','Joined'].includes(a.stage)?'':['Offer Released','Final Evaluation'].includes(a.stage)?'lilac':'gray');
const prio=p=>badge(p,p==='High'?'red':p==='Medium'?'amber':'gray');
const kv=(k,v)=>`<div class="line"><span>${k}</span><strong>${v}</strong></div>`;
const sel=(id,opts,val='',extra='')=>`<select id="${id}" ${extra}><option value="">Choose</option>${opts.map(o=>`<option ${String(val)===String(o)?'selected':''}>${o}</option>`).join('')}</select>`;
const recTabs=()=>tabs(['recruitment','openings','candidates','pipeline','interviews']);
const roleNote=()=>({hr:'You are previewing as HR / Admin: full recruitment access, configuration and reports.',senior:'You are previewing as the senior approver: approves manpower requirements, compensation and final selection.',manager:'You are previewing as a hiring manager: assigned openings, candidates, interviews and feedback. Compensation and identity documents are restricted.'})[recRole()];
const stageStrip=a=>`<div class="stage-strip">${REC_STAGES.map((s,i)=>{const idx=a.stage==='Converted'?11:REC_STAGES.indexOf(a.stage);return `<span class="${i<idx?'done':i===idx?'now':''}">${s}</span>`;}).join('')}${a.stage==='Converted'?'<span class="now">Converted</span>':''}</div>`;
const timeline=items=>items.length?`<ol class="timeline">${items.map(e=>`<li>${esc(e.t)}<small>${esc(e.d)} / ${esc(e.u)}</small></li>`).join('')}</ol>`:'<p class="subtle">No activity yet.</p>';
const feedbackDone=a=>a.interviews.filter(i=>i.status==='Completed').length>0&&a.interviews.filter(i=>i.status==='Completed').every(i=>i.feedback);
const screenComplete=s=>!!(s&&s.resume&&REC_SCREEN.slice(1).every(([k])=>s[k])&&(s.notes||'').trim()&&s.rec);
const prejoinReady=a=>a.prejoin&&a.prejoin.filter(t=>t.mandatory&&t.task!=='Joining confirmation').every(t=>t.done);

function recruitment(){
 const active=recActive(),openJobs=recJobs.filter(j=>j.status==='Open'),ints=recApps.flatMap(a=>a.interviews.map(i=>({...i,app:a})));
 const scheduled=ints.filter(i=>i.status==='Scheduled'),fbPending=ints.filter(i=>i.status==='Completed'&&!i.feedback);
 const week=active.filter(a=>a.offer&&a.offer.status==='Accepted'&&recParse(a.offer.joining)>=recParse(REC_TODAY)&&recParse(a.offer.joining)<recParse(REC_TODAY)+7*86400000);
 const cards=[['Open positions',openJobs.length,openJobs.reduce((n,j)=>n+j.vacancies,0)+' vacancies: '+openJobs.map(j=>j.id).join(', '),'accent'],['Candidates in pipeline',active.length,'Active applications across all stages',''],['Screening pending',active.filter(a=>['New Application','Screening'].includes(a.stage)).length,'Waiting for the screening checklist',''],['Interviews scheduled',scheduled.length,scheduled[0]?'Next: '+scheduled[0].when:'None scheduled',''],['Feedback pending',fbPending.length,'Completed interviews without feedback','purple'],['Selected',active.filter(a=>a.stage==='Selected').length,'Awaiting approval or offer',''],['Offers pending',active.filter(a=>a.stage==='Offer Released').length,'Released, awaiting a response',''],['Offer accepted',active.filter(a=>['Offer Accepted','Pre-Joining'].includes(a.stage)).length,'In pre-joining',''],['Joining this week',week.length,week.map(a=>candOf(a).name+', '+a.offer.joining).join('; ')||'No joining in the next 7 days','accent'],['On hold',recApps.filter(a=>a.outcome&&a.outcome.type==='On Hold').length,'Review dates recorded',''],['Time to hire','23 days','Average from application to selection, last 90 days',''],['Joined this quarter',recApps.filter(a=>['Joined','Converted'].includes(a.stage)).length,'Joined or converted since 1 Jul',''] ];
 const due=active.filter(a=>a.next&&recParse(a.next)<=recParse(REC_TODAY)).sort((x,y)=>recParse(x.next)-recParse(y.next));
 const funnel=REC_STAGES.map(s=>[s,active.filter(a=>a.stage===s).length]);
 return head('HR / RECRUITMENT','One pipeline. Every candidate accounted for.','Manpower requirement to job opening, candidate master, controlled stages, interviews, selection, offer, pre-joining and conversion to employee. Sample date 12 September 2026.',btn('Add candidate','rec-add',true)+btn('Raise a requirement','rec-raise'))+recTabs()+
 notice('Preview role',roleNote())+
 `<div class="grid cols-4">${cards.map(c=>stat(c[0],c[1],c[2],c[3])).join('')}</div>`+
 `<div class="grid split spacer">`+
 card('Needs action today','<p class="subtle">Every active application has an owner and a next action date. These are due today or overdue.</p>'+table(['Candidate','Opening','Stage','Next action','Owner','Due',''],due.map(a=>[person({...candOf(a),title:a.id}),jobOf(a).title+'<br><small class="muted">'+a.job+'</small>',stageBadge(a),esc(a.nextText),esc(a.nextOwner),`<span class="${recOverdue(a.next)?'danger':''}">${a.next}</span>`,btn('Open','rec-app',false,`data-id="${a.id}"`)])),'Who owns the next step, and by when')+
 card('Pipeline by stage',`<div class="funnel">${funnel.map(([s,n])=>`<div class="line"><span>${s}</span><strong>${n}</strong></div><div class="progress"><span style="width:${Math.max(4,n/Math.max(1,active.length)*100)}%"></span></div>`).join('')}</div>`,active.length+' active applications')+
 `</div><div class="grid cols-2 spacer">`+
 card('Reports',`<div class="pill-row">${REC_REPORTS.map(r=>btn(r,'rec-report',false,`data-id="${esc(r)}" class="small-button"`)).join('')}</div><p class="subtle spacer">Each report opens with the columns and filters it will carry. Sample data only.</p>`,'Section 12.2 of the specification')+
 card('Who can see what',table(['User type','Access'],[['HR / Admin','Full recruitment access, configuration and reports'],['Hiring / reporting manager','Assigned openings, candidates, interviews and feedback. Compensation and documents restricted'],['Operations','Only the recruitment and pre-joining information needed for onboarding'],['Candidate (future)','Optional self-service view of application status, documents and forms']])+'<p class="subtle spacer">Compensation, identity documents and personal information are permission-controlled. Switch the preview role at the top right to see the difference.</p>','Section 13.3 of the specification')+
 `</div>`;
}

function openings(){
 const senior=recRole()==='senior',hr=recRole()==='hr';
 return head('HR / REQUIREMENTS AND OPENINGS','A vacancy starts with a requirement.','A manpower requirement is raised and approved first. The approved requirement becomes a job opening that candidates are sourced against.',btn('Raise a requirement','rec-raise',true))+recTabs()+
 `<div class="stepper"><div class="done"><strong>1. Manpower requirement</strong>Raised by the manager</div><div class="done"><strong>2. Approval</strong>Senior approver</div><div class="done"><strong>3. Job opening</strong>Created from the approved requirement</div><div><strong>4. Sourcing</strong>Candidates and applications</div></div>`+
 card('Manpower requirements',table(['ID','Role / department','Positions','Requested by','Reason','Target joining','Priority','Approval',''],recReqs.map(r=>[r.id,esc(r.role)+'<br><small class="muted">'+esc(r.dept)+'</small>',r.positions,esc(r.by),esc(r.reason),r.target,prio(r.priority),badge(r.status,r.status==='Approved'?'':r.status==='Pending'?'amber':'red')+(r.on?'<br><small class="muted">'+esc(r.approver)+', '+r.on+'</small>':''),btn('View','rec-req-view',false,`data-id="${r.id}"`)+(senior&&r.status==='Pending'?' '+btn('Approve','rec-req-approve',true,`data-id="${r.id}"`)+' '+btn('Reject','rec-req-reject',false,`data-id="${r.id}" class="danger"`):'')])),senior?'You can approve or reject the pending requirement.':'Approval is done by the senior approver.')+
 (recReqs.some(r=>r.status==='Pending')&&!senior?notice('One requirement is waiting for approval','MR-0013 was raised on 11 Sep. No job opening exists until it is approved. Switch the preview role to Senior approver to act on it.','amber'):'')+
 card('Job openings','<p class="subtle">Status flow: Draft, Open, On Hold, Closed, Filled, Cancelled.</p>'+table(['ID','Job title','Linked requirement','Location','Vacancies','Experience','Salary range','Hiring owner','Status','Applications',''],recJobs.map(j=>{const apps=recApps.filter(a=>a.job===j.id);return [j.id,'<strong>'+esc(j.title)+'</strong><br><small class="muted">'+esc(j.dept)+'</small>',j.req,esc(j.location),j.vacancies,esc(j.exp),pay(j.ctc),esc(j.owner),badge(j.status,j.status==='Open'?'':j.status==='Draft'?'amber':'gray'),apps.filter(a=>!a.outcome&&a.stage!=='Converted').length+' active / '+apps.length+' total',btn('View','rec-job-view',false,`data-id="${j.id}"`)+(hr&&j.status==='Draft'?' '+btn('Publish','rec-job-open',true,`data-id="${j.id}"`):'')];})),'Sourcing runs against an opening, never against a bare requirement');
}

function candidates(){
 const q=state.rec.search.trim().toLowerCase();
 const rows=recCandidates.filter(c=>{const apps=recApps.filter(a=>a.cand===c.id);if(state.rec.source&&c.source!==state.rec.source)return false;if(state.rec.stageF&&!apps.some(a=>(a.outcome?a.outcome.type:a.stage)===state.rec.stageF))return false;if(!q)return true;return [c.id,c.name,c.mobile,c.email,c.city,c.company,c.designation,...c.skills,...apps.map(a=>a.job)].some(v=>String(v).toLowerCase().includes(q));});
 return head('HR / CANDIDATE MASTER','One record per person.','A candidate is a person; an application is that person considered for one opening. The same candidate can have several applications and is never duplicated.',btn('Add candidate','rec-add',true))+recTabs()+
 `<div class="wa-filters"><input id="rec-search" type="search" placeholder="Search by candidate ID, name, mobile, email, city, skill or opening" value="${esc(state.rec.search)}" autocomplete="off"><label class="inline">Source ${sel('rec-source',['Referral','Portal','Consultant','Direct','Website','Other'],state.rec.source)}</label><label class="inline">Stage ${sel('rec-stage',[...REC_STAGES,'Converted','Rejected','On Hold','Offer Declined','Candidate Withdrawn'],state.rec.stageF)}</label></div>`+
 card(rows.length+' candidates',table(['Candidate','Contact','City','Source','Experience','Current role','Applications','Latest stage',''],rows.map(c=>{const apps=recApps.filter(a=>a.cand===c.id);const latest=apps.slice().sort((x,y)=>recParse(y.date)-recParse(x.date))[0];return [person({...c,title:c.id}),esc(c.mobile)+'<br><small class="muted">'+esc(c.email)+'</small>',esc(c.city),esc(c.source)+'<br><small class="muted">'+esc(c.sourceDetail)+'</small>',esc(c.exp)+'<br><small class="muted">'+esc(c.relExp)+' relevant</small>',esc(c.designation)+'<br><small class="muted">'+esc(c.company)+'</small>',apps.map(a=>`<small>${a.id} / ${a.job}</small>`).join('<br>'),latest?stageBadge(latest):badge('No application','gray'),btn('Open','rec-cand',false,`data-id="${c.id}"`)];})),'Search and filter by ID, name, mobile, email, source, opening, stage, owner and dates')+
 notice('Duplicate prevention','Before a candidate is created the mobile number, email and name are checked. Try adding a candidate with mobile 98200 00219 to see the warning.');
}

function candidate(){
 const c=recCandidates.find(x=>x.id===state.rec.cand)||recCandidates[0],apps=recApps.filter(a=>a.cand===c.id),docs=recDocsFor(c.id),hr=recRole()==='hr';
 const events=apps.flatMap(a=>a.timeline.map(e=>({...e,app:a.id}))).sort((x,y)=>recParse(x.d.split(',')[0])-recParse(y.d.split(',')[0]));
 return head('HR / CANDIDATE PROFILE',esc(c.name),c.id+' / '+esc(c.designation)+' at '+esc(c.company)+' / '+esc(c.city),link('Back to candidates','candidates')+btn('Add application for this candidate','rec-add-app',true,`data-id="${c.id}"`))+recTabs()+
 `<div class="card"><div class="profile-top">${avatar({...c,initials:c.initials}).replace('class="avatar','class="avatar large')}<div><h2>${esc(c.name)}</h2><div class="profile-meta"><span>${esc(c.mobile)}</span><span>${esc(c.email)}</span><span>Source: ${esc(c.source)}, ${esc(c.sourceDetail)}</span><span>Notice: ${esc(c.notice)}</span></div><div class="pill-row spacer">${c.skills.map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div></div></div></div>`+
 `<div class="grid split spacer"><div>`+
 card('Applications',table(['Application','Opening','Applied','Stage / outcome','Next action',''],apps.map(a=>[a.id,jobOf(a).title+'<br><small class="muted">'+a.job+', '+esc(jobOf(a).location)+'</small>',a.date+'<br><small class="muted">'+esc(a.source)+'</small>',stageBadge(a),a.outcome?esc(a.outcome.reason):esc(a.nextText)+(a.next?'<br><small class="muted">'+a.next+', '+esc(a.nextOwner)+'</small>':''),btn('Open','rec-app',false,`data-id="${a.id}"`)])),apps.length+' application'+(apps.length===1?'':'s')+' linked to this one candidate record')+
 `<div class="grid cols-2 spacer">`+card('Personal and contact',kv('Candidate ID',c.id)+kv('Full name',esc(c.name))+kv('Gender',esc(c.gender))+kv('Mobile',esc(c.mobile))+kv('Alternate mobile',esc(c.alt||'Not given'))+kv('Email',esc(c.email))+kv('Current city',esc(c.city))+kv('Current address',esc(c.address))+kv('Permanent address',esc(c.permanent))+kv('Preferred location',esc(c.pref))+kv('LinkedIn',esc(c.linkedin||'Not given'))+kv('Source',esc(c.source)+', '+esc(c.sourceDetail)))+
 card('Professional profile',kv('Current company',esc(c.company))+kv('Current designation',esc(c.designation))+kv('Total experience',esc(c.exp))+kv('Relevant experience',esc(c.relExp))+kv('Current CTC',pay(c.ctc))+kv('Expected CTC',pay(c.ectc))+kv('Notice period',esc(c.notice))+kv('Expected joining',esc(c.joinBy))+kv('Reason for change',esc(c.reason))+kv('Certifications',esc(c.certs||'None recorded'))+kv('Industry experience',esc(c.industry))+kv('Resume',esc(c.resume)))+`</div></div><div>`+
 card('Documents',docs.map(d=>`<div class="document"><span class="file-icon">${d.status==='Verified'?'OK':'DOC'}</span><div class="file-copy"><strong>${esc(d.name)}</strong><small>Mandatory: ${esc(d.mandatory)} / Stage: ${esc(d.stage)}${d.by?' / Verified by '+esc(d.by)+', '+d.on:''}</small></div>${badge(d.status,d.status==='Verified'?'':['Requested','Under review','Submitted'].includes(d.status)?'amber':d.status==='Rejected'?'red':'gray')}${hr&&['Submitted','Under review'].includes(d.status)?btn('Verify','rec-doc-verify',false,`data-id="${c.id}|${esc(d.name)}"`):''}</div>`).join('')+'<p class="subtle spacer">Every document keeps its uploaded date, uploaded by, verification status, verified by, verification date and remarks. Identity documents are restricted to HR.</p>','Section 9, stored against the candidate and kept after conversion')+
 card('Activity timeline',timeline(events.map(e=>({...e,t:'['+e.app+'] '+e.t}))),'Chronological and immutable. Calls, emails, messages, interviews, tasks, notes, documents and stage changes')+
 `</div></div>`;
}

function pipeline(){
 const active=recActive().filter(a=>(!state.rec.jobFilter||a.job===state.rec.jobFilter)&&(!state.rec.ownerFilter||a.owner===state.rec.ownerFilter));
 const closed=recApps.filter(a=>a.outcome||a.stage==='Converted');
 return head('HR / APPLICATION PIPELINE','Move candidates with actions, not by editing a field.','Each column is a controlled stage. A candidate moves only through the allowed action for that stage, and only after the mandatory information for the move is complete.',link('Interviews','interviews'))+recTabs()+
 `<div class="wa-filters"><label class="inline">Job opening ${sel('rec-jobfilter',recJobs.map(j=>j.id+' '+j.title),state.rec.jobFilter?state.rec.jobFilter+' '+recJobs.find(j=>j.id===state.rec.jobFilter).title:'')}</label><label class="inline">Owner ${sel('rec-ownerfilter',['Meera Demo'],state.rec.ownerFilter)}</label><span class="subtle">${active.length} active applications. Scroll sideways for later stages.</span></div>`+
 `<div class="board">${REC_STAGES.map(s=>{const col=active.filter(a=>a.stage===s);return `<div class="col"><h3><span>${s}</span><span>${col.length}</span></h3>${col.map(a=>`<button type="button" class="ticket ${recOverdue(a.next)?'due':''}" data-action="rec-app" data-id="${a.id}"><strong>${esc(candOf(a).name)}</strong><small>${esc(jobOf(a).title)} / ${a.job}</small><small>${esc(a.nextText)}</small><span class="ticket-foot">${prio(a.priority)}<small>${a.next?(recOverdue(a.next)?'Overdue ':'Due ')+a.next:''}</small></span></button>`).join('')||'<p class="subtle">None</p>'}</div>`;}).join('')}</div>`+
 `<div class="grid cols-2 spacer">`+card('Allowed actions by stage',table(['Stage','Allowed next actions','Mandatory before the move'],REC_STAGES.map(s=>[s,REC_RULES[s].next,REC_RULES[s].must])),'Section 10. The stage field is never edited directly')+
 card('Closed and paused',table(['Candidate','Opening','Outcome','Reason','Date',''],closed.map(a=>[esc(candOf(a).name),a.job,stageBadge(a),esc(a.outcome?a.outcome.reason+(a.outcome.review?'. Review on '+a.outcome.review:''):'Converted to employee on '+(a.converted||'')),a.outcome?a.outcome.on:(a.converted||''),btn('Open','rec-app',false,`data-id="${a.id}"`)])),'Rejected, on hold, declined, withdrawn, deferred, and converted records stay visible')+`</div>`;
}

function interviews(){
 const ints=recApps.filter(a=>!a.outcome).flatMap(a=>a.interviews.map(i=>({...i,app:a}))).sort((x,y)=>recParse(x.when.split(',')[0])-recParse(y.when.split(',')[0]));
 const upcoming=ints.filter(i=>i.status==='Scheduled'),pending=ints.filter(i=>i.status==='Completed'&&!i.feedback),done=ints.filter(i=>i.status==='Completed'&&i.feedback);
 return head('HR / INTERVIEWS','Rounds, not repeat records.','One application can have several interview rounds. Each round has its own schedule, interviewers, confirmation and structured feedback.')+recTabs()+
 (pending.length?notice(pending.length+' interview'+(pending.length===1?' is':'s are')+' waiting for feedback','A candidate cannot move to final evaluation until every completed round has feedback. Pending: '+pending.map(i=>esc(candOf(i.app).name)+' ('+i.round+', '+esc(i.interviewers)+')').join('; ')+'.','amber'):'')+
 card('Upcoming interviews',table(['When','Candidate','Opening','Round','Type','Mode','Location / link','Interviewers','Candidate confirmation','Reminder','Status',''],upcoming.map(i=>[i.when,esc(candOf(i.app).name),i.app.job,i.round,i.type,i.mode,esc(i.where||'Phone'),esc(i.interviewers),badge(i.confirm,i.confirm==='Confirmed'?'':'amber'),'Automated, 1 day before',badge(i.status,'lilac'),btn('Open application','rec-app',false,`data-id="${i.app.id}"`)])),'Section 5.1')+
 card('Feedback pending',pending.length?table(['Interview','Candidate','Round','Interviewer','Completed on',''],pending.map(i=>[i.id,esc(candOf(i.app).name),i.round+', '+i.type,esc(i.interviewers),i.when,btn('Record feedback','rec-int-feedback',true,`data-id="${i.app.id}|${i.id}"`)])):'<p class="subtle">No feedback pending.</p>','Completed interviews without structured feedback')+
 card('Completed with feedback',table(['Interview','Candidate','Round','Interviewer','Overall','Recommendation','Date',''],done.map(i=>[i.id,esc(candOf(i.app).name),i.round+', '+i.type,esc(i.interviewers),i.feedback.overall+' / 5',badge(i.feedback.rec,['Strong Hire','Hire'].includes(i.feedback.rec)?'':i.feedback.rec==='Reject'?'red':'amber'),i.feedback.on,btn('View','rec-int-view',false,`data-id="${i.app.id}|${i.id}"`)])),'Section 5.2');
}

function application(){
 const a=appOf(state.rec.app)||recApps[1],c=candOf(a),j=jobOf(a),role=recRole(),hr=role==='hr',senior=role==='senior',docs=recDocsFor(c.id);
 const rules=REC_RULES[a.stage]||REC_RULES.Joined;
 let main='';
 if(a.outcome){main=notice('Outcome: '+a.outcome.type,'Reason: '+esc(a.outcome.reason)+'. Recorded '+a.outcome.on+(a.outcome.review?'. Next review on '+a.outcome.review:'')+'. The application stays visible as recruitment history.',a.outcome.type==='On Hold'?'amber':'');}
 if(a.stage==='New Application'&&!a.outcome){main+=card('Application record',`<div class="grid cols-2">${kv('Application ID',a.id)+kv('Candidate',esc(c.name)+', '+c.id)+kv('Job opening',esc(j.title)+', '+j.id)+kv('Application date',a.date)+kv('Application source',esc(a.source))+kv('Application owner',esc(a.owner))+kv('Current stage',a.stage)+kv('Current status',esc(a.status))+kv('Priority',esc(a.priority))+kv('Last action',a.timeline[a.timeline.length-1].d)+kv('Next action date',a.next)+kv('Next action owner',esc(a.nextOwner))}</div>${kv('Application notes',esc(a.notes||'None'))}<div class="actions spacer">${btn('Start screening','rec-screen-start',true)}</div>`,'Section 4.1');}
 if(a.stage==='Screening'&&!a.outcome){const s=a.screening||{};const complete=screenComplete(s);main+=card('Initial screening',`<p class="subtle">Every field below is mandatory. The candidate cannot be moved to the interview stage until the checklist and recommendation are complete.</p>${REC_SCREEN.map(([k,label,type])=>`<div class="check"><span class="grow">${label}</span>${type==='check'?`<input type="checkbox" id="rec-s-${k}" ${s[k]?'checked':''}>`:type==='yn'?sel('rec-s-'+k,['Yes','No'],s[k]):sel('rec-s-'+k,['1','2','3','4','5'],s[k])}</div>`).join('')}<label class="spacer">Screening notes<textarea id="rec-s-notes" placeholder="What was reviewed, what was confirmed on the call, what is missing">${esc(s.notes||'')}</textarea></label><label class="spacer">Screening recommendation ${sel('rec-s-rec',['Shortlist','Reject','Hold','Need More Information','Move to Interview'],s.rec)}</label>${kv('Screened by',esc(s.by||recUser()))+kv('Screening date',s.on||REC_TODAY)}<div class="actions spacer">${btn('Save checklist','rec-screen-save',false)}${btn('Move to interview (shortlist)','rec-shortlist',true,complete&&['Shortlist','Move to Interview'].includes(s.rec)?'':'disabled')}${btn('Need more information','rec-need-info')}</div>${complete?'':notice('Move blocked','Complete every mandatory field and choose Shortlist or Move to Interview to enable the move.','amber')}`,'Section 4.2');}
 if(['Shortlisted','Interview Scheduled','Interview Completed','Final Evaluation'].includes(a.stage)&&!a.outcome){main+=card('Interview rounds',(a.interviews.length?table(['Interview','Round','Type','Mode','Date and time','Location / link','Interviewers','Confirmation','Status','Feedback',''],a.interviews.map(i=>[i.id,i.round,i.type,i.mode,i.when,esc(i.where||'Phone'),esc(i.interviewers),badge(i.confirm,i.confirm==='Confirmed'?'':'amber'),badge(i.status,i.status==='Completed'?'':i.status==='Scheduled'?'lilac':'gray'),i.feedback?badge(i.feedback.rec,['Strong Hire','Hire'].includes(i.feedback.rec)?'':i.feedback.rec==='Reject'?'red':'amber'):i.status==='Completed'?badge('Pending','amber'):'',i.status==='Scheduled'?btn('Mark completed','rec-int-complete',false,`data-id="${i.id}"`)+' '+btn('Reschedule','rec-int-resched',false,`data-id="${i.id}"`):i.status==='Completed'&&!i.feedback?btn('Record feedback','rec-int-feedback',true,`data-id="${a.id}|${i.id}"`):i.feedback?btn('View feedback','rec-int-view',false,`data-id="${a.id}|${i.id}"`):''])):'<p class="subtle">No interview scheduled yet.</p>')+`<div class="actions spacer">${btn(a.interviews.length?'Schedule a further round':'Schedule interview','rec-schedule',a.stage==='Shortlisted'||a.stage==='Interview Completed')}${a.stage==='Interview Completed'?btn('Move to final evaluation','rec-eval',true,feedbackDone(a)?'':'disabled'):''}${a.stage==='Final Evaluation'?btn('Record final selection','rec-select',true):''}</div>`+(a.stage==='Interview Completed'&&!feedbackDone(a)?notice('Move blocked','Every completed round needs structured feedback before final evaluation. Pending: '+a.interviews.filter(i=>i.status==='Completed'&&!i.feedback).map(i=>i.round+' by '+esc(i.interviewers)).join(', ')+'.','amber'):''),'Sections 5.1 and 5.2. Role-specific feedback rows for '+j.role);}
 if(a.stage==='Final Evaluation'&&!a.outcome){main+=card('Final evaluation summary',table(['Round','Interviewer','Overall','Recommendation','Strengths','Concerns'],a.interviews.filter(i=>i.feedback).map(i=>[i.round+', '+i.type,esc(i.interviewers),i.feedback.overall+' / 5',esc(i.feedback.rec),esc(i.feedback.strengths),esc(i.feedback.concerns||'None recorded')]))+notice('All mandatory feedback received','Final interview completed: yes. Feedback received for every round: yes. The candidate can now be selected, held or rejected with a recorded evaluation.'),'Section 7');}
 if(['Selected','Offer Released','Offer Accepted','Pre-Joining','Joined','Converted'].includes(a.stage)&&a.selection){const s=a.selection;const steps=[['Interview recommendation',true],['Final selection',true],['Compensation approval',a.approval>=3],['Final approval',a.approval>=4],['Offer preparation',!!a.offer]];main+=card('Final selection and approval',`<div class="stepper">${steps.map(([n,d])=>`<div class="${d?'done':''}"><strong>${n}</strong>${d?'Done':'Pending'}</div>`).join('')}</div><div class="grid cols-2">${kv('Final recommendation',esc(s.finalRec))+kv('Decision',esc(s.decision))+kv('Selected role',esc(s.role))+kv('Selected designation',esc(s.designation))+kv('Reporting manager',esc(s.manager))+kv('Work location',esc(s.location))+kv('Proposed joining date',esc(s.joining))+kv('Approved CTC',pay(s.ctc))+kv('Incentive / variable pay',pay(s.incentive))+kv('Probation period',esc(s.probation))+kv('Notice period',esc(s.notice))+kv('Final approver',esc(s.approver)+(s.on?', '+s.on:', pending'))}</div>${kv('Selection remarks',esc(s.remarks||'None'))}${a.stage==='Selected'?`<div class="actions spacer">${senior&&a.approval===2?btn('Approve compensation','rec-approve-comp',true):''}${senior&&a.approval===3?btn('Give final approval','rec-approve-final',true):''}${hr&&a.approval>=4?btn('Prepare and release offer','rec-offer',true):''}${!senior&&a.approval<4?notice('Waiting for the senior approver','Compensation approval and final approval are recorded by the senior approver. Switch the preview role to act.','amber'):''}</div>`:''}`,'Sections 7.1 and 7.2. Approvers are configurable');}
 if(a.offer){const o=a.offer;main+=card('Offer '+o.id,`<div class="grid cols-2">${kv('Offer date',o.date)+kv('Offer status',badge(o.status,o.status==='Accepted'?'':o.status==='Released'?'lilac':o.status==='Draft'?'amber':'red'))+kv('Role / designation',esc(o.role))+kv('Department',esc(o.dept))+kv('Reporting manager',esc(o.manager))+kv('Location',esc(o.location))+kv('Joining date',esc(o.joining))+kv('CTC',pay(o.ctc))+kv('Fixed pay',pay(o.fixed))+kv('Variable / incentive',pay(o.variable))+kv('Probation',esc(o.probation))+kv('Notice period',esc(o.notice))+kv('Offer letter',esc(o.letter))+kv('Acceptance date',esc(o.acceptedOn||'Pending'))}</div>${kv('Candidate remarks',esc(o.remarks||'None'))}${a.stage==='Offer Released'&&hr?`<div class="actions spacer">${btn('Record acceptance','rec-offer-accept',true)}${btn('Record decline','rec-offer-decline')}${btn('Withdraw offer','rec-offer-withdraw',false,'class="danger"')}</div>`:''}`,'Section 8. Every version of the offer is retained');}
 if(a.stage==='Offer Accepted'&&!a.outcome){main+=notice('Pre-joining checklist opened automatically','Acceptance on '+a.offer.acceptedOn+', joining '+a.offer.joining+'. Start pre-joining to assign the checklist owners.')+`<div class="actions">${btn('Start pre-joining','rec-prejoin-start',true)}${btn('Joining deferred','rec-defer')}</div>`;}
 if(a.prejoin&&['Pre-Joining','Joined','Converted'].includes(a.stage)){const done=a.prejoin.filter(t=>t.done).length;main+=card('Pre-joining checklist',`<div class="progress"><span style="width:${done/a.prejoin.length*100}%"></span></div><p class="subtle">${done} of ${a.prejoin.length} complete. Joining ${a.offer.joining}.</p>${a.prejoin.map((t,i)=>`<div class="check"><input type="checkbox" ${t.done?'checked':''} ${a.stage==='Pre-Joining'&&(hr||role==='senior')?`data-action="rec-prejoin-tick" data-id="${i}"`:'disabled'} aria-label="${esc(t.task)}"><span class="grow"><strong>${esc(t.task)}</strong>${t.mandatory?'':' <span class="tag">if applicable</span>'}<br><small class="muted">${esc(t.owner)} / ${esc(t.trigger)}</small></span>${t.done?badge('Done'):badge('Open','amber')}</div>`).join('')}${a.stage==='Pre-Joining'?`<div class="actions spacer">${btn('Mark joined','rec-joined',true,prejoinReady(a)?'':'disabled')}${btn('Joining deferred','rec-defer')}</div>${prejoinReady(a)?'':notice('Move blocked','Every mandatory item must be complete before the candidate is marked as joined.','amber')}`:''}`,'Section 8.1. Owners per task');}
 if(a.stage==='Joined'){main+=card('Convert to employee',`<p class="subtle">Joined on ${a.joinedOn}. The recruitment record becomes the source for the employee master. Nothing is discarded.</p><div class="actions spacer">${hr?btn('Convert to employee','rec-convert',true):notice('HR action','Conversion is done by HR / Admin.','amber')}</div>`,'Section 14');}
 if(a.stage==='Converted'){main+=notice('Converted to employee on '+a.converted,'Employee code '+a.employeeCode+' created in the employee hub with name, contact, role, department, reporting manager, location, joining date, approved compensation, offer records, verified documents, interview history and source. This application is now read-only recruitment history.')+`<div class="actions">${link('Open the employee hub','people')}</div>`;}
 const rightDocs=docs.filter(d=>d.status!=='Not applicable yet'&&d.status!=='Not yet requested');
 return head('HR / APPLICATION '+a.id,esc(c.name)+' for '+esc(j.title),'Owner '+esc(a.owner)+'. Next action: '+(a.outcome?'none, '+a.outcome.type.toLowerCase():esc(a.nextText)+' by '+esc(a.nextOwner)+' on '+a.next)+'.',stageBadge(a)+link('Back to pipeline','pipeline'))+recTabs()+stageStrip(a)+
 `<div class="grid split"><div>`+
 card('Where this candidate is',`<div class="grid cols-2">${kv('Current stage',a.stage)+kv('Status',esc(a.status))+kv('Allowed next actions',rules.next)+kv('Mandatory before the move',rules.must)+kv('Owner',esc(a.owner))+kv('Priority',prio(a.priority))}</div>${!a.outcome&&!['Joined','Converted'].includes(a.stage)?`<div class="actions spacer">${btn('Reject','rec-reject',false,'class="danger"')}${btn('Put on hold','rec-hold')}${btn('Candidate withdrew','rec-withdraw')}</div>`:''}`,'The pipeline decides what is possible next')+main+
 `</div><div>`+card('Candidate',`${person({...c,title:esc(c.designation)+', '+esc(c.company)})}<div class="spacer">${kv('Mobile',esc(c.mobile))+kv('Email',esc(c.email))+kv('City',esc(c.city))+kv('Experience',esc(c.exp)+' total, '+esc(c.relExp)+' relevant')+kv('Notice period',esc(c.notice))+kv('Expected CTC',pay(c.ectc))+kv('Source',esc(c.source)+', '+esc(c.sourceDetail))}</div><div class="actions spacer">${btn('Full profile','rec-cand',false,`data-id="${c.id}"`)}</div>`)+
 card('Role criteria for '+j.role,REC_CRITERIA[j.role].map(([k,v])=>`<div class="crit"><strong>${k}</strong><small>${v}</small></div>`).join(''),'Section 6, configurable per job opening')+
 card('Documents',rightDocs.length?rightDocs.map(d=>`<div class="document"><span class="file-icon">${d.status==='Verified'?'OK':'DOC'}</span><div class="file-copy"><strong>${esc(d.name)}</strong><small>${esc(d.stage)}${d.by?' / '+esc(d.by)+', '+d.on:''}</small></div>${badge(d.status,d.status==='Verified'?'':['Requested','Under review','Submitted'].includes(d.status)?'amber':'gray')}</div>`).join(''):'<p class="subtle">Only the resume so far. Pre-joining documents are requested after offer acceptance.</p>')+
 card('Activity timeline',timeline(a.timeline),'Chronological and immutable')+`</div></div>`;
}

