modules.push({id:'recruitment',number:'07',title:'Recruitment',text:'Manpower requirement to job opening, one candidate master, a controlled pipeline with interviews, selection, offer, pre-joining and conversion to employee.',screens:['recruitment','openings','candidates','candidate','pipeline','application','interviews'],video:null,refs:'Recruitment process specification, sections 1 to 15, received 12 Sep 2026',question:'Confirm who approves a manpower requirement and compensation, the interview rounds per role, the mandatory pre-joining documents, and whether a duplicate candidate may ever be created with a reason.'});

function recReasonDialog(kind,title,text,extra=''){dialog(title,`<form id="rec-reason-form" data-kind="${kind}" novalidate><p class="subtle">${text}</p><label class="spacer">Reason <span aria-hidden="true">*</span><textarea name="reason" placeholder="Mandatory. This is written to the timeline."></textarea></label>${extra}<p id="rec-reason-error" class="error" role="alert"></p><button class="primary">Record</button></form>`);}
function recSetOutcome(a,type,reason,review){a.outcome={type,reason,on:REC_TODAY,review:review||''};a.status=type;a.next=review||'';a.nextText=review?'Review the hold':'';a.nextOwner=review?a.owner:'';recLog(a,'Outcome: '+type+(review?' until '+review:'')+'. Reason: '+reason);}
function recFeedbackForm(a,i){const j=jobOf(a),rows=[...REC_FB_COMMON,...(REC_FB_ROLE[j.role]||[]),...REC_FB_TAIL];return `<form id="rec-fb-form" data-app="${a.id}" data-int="${i.id}" novalidate><p class="subtle">${i.round}, ${i.type}, ${i.when}. Interviewer: ${esc(i.interviewers)}. Rows marked ${j.role} are shown because this opening is a ${j.role} role.</p><div class="score-config spacer">${rows.map(([k,label])=>`<label>${label}${(REC_FB_ROLE[j.role]||[]).some(r=>r[0]===k)?' <span class="tag">'+j.role+'</span>':''}<select name="${k}"><option value="">Rate</option>${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label>`).join('')}</div><label class="spacer">Strengths <span aria-hidden="true">*</span><textarea name="strengths"></textarea></label><label class="spacer">Concerns / gaps<textarea name="concerns"></textarea></label><label class="spacer">Final recommendation <span aria-hidden="true">*</span><select name="rec"><option value="">Choose</option>${['Strong Hire','Hire','Further Round','Hold','Reject'].map(o=>`<option>${o}</option>`).join('')}</select></label><label class="spacer">Feedback remarks <span aria-hidden="true">*</span><textarea name="remarks"></textarea></label>${kv('Interviewer',recUser())+kv('Feedback date',REC_TODAY)}<p id="rec-fb-error" class="error" role="alert"></p><button class="primary">Submit feedback</button></form>`;}
function recAction(a,id){
 const app=appOf(state.rec.app);
 switch(a){
 case 'rec-close':closeDialog();break;
 case 'rec-cand':state.rec.cand=id;location.hash='candidate';break;
 case 'rec-app':state.rec.app=id;location.hash='application';break;
 case 'rec-report':dialog(esc(id),`<p class="subtle">Sample layout. Columns and filters follow the specification fields for this report.</p>${kv('Filters','Date range, job opening, role, owner, source, stage, status')+kv('Grouping',id.includes('Role')?'Role, then opening':id.includes('owner')?'Owner, then stage':id.includes('Source')?'Source, then outcome':'Stage')+kv('Export','Excel and PDF')+kv('Refresh','Live from the pipeline')}`);break;
 case 'rec-raise':dialog('Raise a manpower requirement',`<form id="rec-req-form" novalidate><div class="form-grid"><label>Requirement ID<input value="MR-0014" readonly></label><label>Requested by<input value="${recUser()}" readonly></label><label>Role ${sel('rec-r-role',['RM','Operations'],'','name="role"')}</label><label>Department ${sel('rec-r-dept',['Client relationships','Operations','Administration'],'','name="dept"')}</label><label>No. of positions<input name="positions" type="number" min="1" value="1"></label><label>Reason for hiring ${sel('rec-r-reason',['New position','Replacement','Expansion','Other'],'','name="reason"')}</label><label>Reporting manager<input name="manager" placeholder="Proposed reporting person"></label><label>Work location ${sel('rec-r-loc',['Pune, Kothrud office','Nashik branch','Mumbai, remote with weekly visits'],'','name="location"')}</label><label>Employment type ${sel('rec-r-type',['Full-time','Part-time','Contract','Intern'],'Full-time','name="type"')}</label><label>Required experience<input name="exp" placeholder="e.g. 2 to 5 years"></label><label class="full">Required skills<input name="skills" placeholder="Comma separated"></label><label>Budget / salary range<input name="budget" placeholder="e.g. Rs 5.0 L to 7.5 L"></label><label>Target joining date<input name="target" type="date"></label><label>Priority ${sel('rec-r-prio',['High','Medium','Low'],'','name="priority"')}</label><label>Approval status<input value="Pending" readonly></label><label class="full">Job description<textarea name="jd" placeholder="Detailed role description"></textarea></label><label class="full">Remarks<textarea name="remarks"></textarea></label></div><p id="rec-req-error" class="error" role="alert"></p><button class="primary">Submit for approval</button></form>`);break;
 case 'rec-req-view':{const r=recReqs.find(x=>x.id===id);dialog(r.id+' / manpower requirement',`<div class="grid cols-2">${kv('Requested by',esc(r.by))+kv('Role / department',esc(r.role)+', '+esc(r.dept))+kv('Positions',r.positions)+kv('Reason for hiring',esc(r.reason))+kv('Reporting manager',esc(r.manager))+kv('Work location',esc(r.location))+kv('Employment type',esc(r.type))+kv('Required experience',esc(r.exp))+kv('Budget / salary range',pay(r.budget))+kv('Target joining date',r.target)+kv('Priority',esc(r.priority))+kv('Approval',esc(r.status)+(r.on?', '+esc(r.approver)+', '+r.on:''))}</div>${kv('Required skills',esc(r.skills))+kv('Job description',esc(r.jd))+kv('Remarks',esc(r.remarks||'None'))}`);break;}
 case 'rec-req-approve':{const r=recReqs.find(x=>x.id===id);if(recRole()!=='senior'||!r||r.status!=='Pending')break;r.status='Approved';r.approver=recUser()+' (senior approver)';r.on=REC_TODAY;const jid='JOB-0009';recJobs.push({id:jid,title:r.role==='RM'?'Relationship Manager':'Operations Executive',req:r.id,role:r.role,dept:r.dept,location:r.location,vacancies:r.positions,exp:r.exp,qual:'Graduate',skills:r.skills,ctc:r.budget,incentive:r.role==='RM'?'Quarterly, on net sales':'Not applicable',notice:'Up to 30 days',deadline:'',status:'Draft',owner:'Meera Demo (HR)',created:REC_TODAY,modified:REC_TODAY});render();showToast(r.id+' approved. Job opening '+jid+' created as a draft for HR to complete and publish.');break;}
 case 'rec-req-reject':if(recRole()==='senior')recReasonDialog('req:'+id,'Reject requirement '+id,'The reason is stored with the requirement and shown to the person who raised it.');break;
 case 'rec-job-view':{const j=recJobs.find(x=>x.id===id);const apps=recApps.filter(x=>x.job===j.id);dialog(j.id+' / '+esc(j.title),`<div class="grid cols-2">${kv('Linked requirement',j.req)+kv('Role / department',esc(j.role)+', '+esc(j.dept))+kv('Location',esc(j.location))+kv('Vacancies',j.vacancies)+kv('Experience range',esc(j.exp))+kv('Qualification',esc(j.qual))+kv('Salary range / CTC',pay(j.ctc))+kv('Incentive structure',pay(j.incentive))+kv('Notice period preference',esc(j.notice))+kv('Application deadline',j.deadline||'Open')+kv('Status',esc(j.status))+kv('Hiring owner',esc(j.owner))+kv('Created',j.created)+kv('Modified',j.modified)}</div>${kv('Skills / competencies',esc(j.skills))}<h3 class="spacer">Applications</h3>${apps.length?table(['Application','Candidate','Stage'],apps.map(x=>[x.id,esc(candOf(x).name),stageBadge(x)])):'<p class="subtle">None yet.</p>'}`);break;}
 case 'rec-job-open':{const j=recJobs.find(x=>x.id===id);if(j&&j.status==='Draft'&&recRole()==='hr'){j.status='Open';j.modified=REC_TODAY;render();showToast(j.id+' is now open for sourcing.');}break;}
 case 'rec-add':case 'rec-add-app':{const c=a==='rec-add-app'?recCandidates.find(x=>x.id===id):null;const jobs=recJobs.filter(j=>j.status==='Open');dialog(c?'New application for '+esc(c.name):'Add candidate',`<form id="rec-cand-form" data-existing="${c?c.id:''}" novalidate>${c?'':`<div class="form-grid"><label>First name<input name="first"></label><label>Middle name<input name="middle"></label><label>Last name<input name="last"></label><label>Mobile number <span aria-hidden="true">*</span><input name="mobile" placeholder="10 digits"></label><label>Alternate mobile<input name="alt"></label><label>Email ID <span aria-hidden="true">*</span><input name="email" type="email"></label><label>Current city <span aria-hidden="true">*</span><input name="city"></label><label>Preferred location<input name="pref"></label><label class="full">Current address<input name="address"></label><label>LinkedIn / profile<input name="linkedin"></label><label>Source <span aria-hidden="true">*</span>${sel('rec-c-source',['Referral','Portal','Consultant','Direct','Website','Other'],'','name="source"')}</label><label class="full">Source details<input name="sourceDetail" placeholder="Referrer, portal or consultant name"></label><label>Current company<input name="company"></label><label>Current designation<input name="designation"></label><label>Total experience <span aria-hidden="true">*</span><input name="exp" placeholder="Years and months"></label><label>Relevant experience <span aria-hidden="true">*</span><input name="relExp"></label><label>Expected CTC <span aria-hidden="true">*</span><input name="ectc"></label><label>Notice period <span aria-hidden="true">*</span><input name="notice"></label><label class="full">Key skills <span aria-hidden="true">*</span><input name="skills" placeholder="Comma separated"></label><label class="full">Resume <span aria-hidden="true">*</span><input type="file" disabled><small class="muted">No file is uploaded in this preview.</small></label></div>`}<label class="spacer">Job opening <span aria-hidden="true">*</span>${sel('rec-c-job',jobs.map(j=>j.id+' '+j.title),'','name="job"')}</label><label class="spacer">Application source ${sel('rec-c-asource',['Referral','Portal','Consultant','Direct','Website','Other'],c?c.source:'','name="asource"')}</label><label class="spacer">Priority ${sel('rec-c-prio',['High','Medium','Low'],'Medium','name="priority"')}</label><p id="rec-cand-error" class="error" role="alert"></p><div id="rec-dup"></div><button class="primary">${c?'Create application':'Check for duplicates and create'}</button></form>`);break;}
 case 'rec-screen-start':if(app&&app.stage==='New Application'){app.screening={};app.status='Checklist in progress';app.nextText='Complete the screening checklist';app.next='13 Sep 2026';app.nextOwner=recUser();recMove(app,'Screening');render();showToast('Screening started. The checklist must be complete before the candidate can move to interview.');}break;
 case 'rec-screen-save':case 'rec-shortlist':case 'rec-need-info':{if(!app||app.stage!=='Screening')break;const s=app.screening||{};REC_SCREEN.forEach(([k,,type])=>{const el=$('#rec-s-'+k);s[k]=type==='check'?!!(el&&el.checked):(el?el.value:'');});s.notes=$('#rec-s-notes')?.value||'';s.rec=$('#rec-s-rec')?.value||'';s.by=recUser();s.on=REC_TODAY;app.screening=s;if(a==='rec-screen-save'){render();showToast('Checklist saved. '+(screenComplete(s)?'All mandatory fields are complete.':'Some mandatory fields are still empty.'));break;}if(a==='rec-need-info'){app.status='Need more information';app.nextText='Collect the missing information';recLog(app,'Screening: need more information. '+(s.notes||''));render();showToast('Recorded. The candidate stays in Screening.');break;}if(!screenComplete(s)||!['Shortlist','Move to Interview'].includes(s.rec)){render();showToast('Move blocked: complete every mandatory screening field and choose Shortlist.');break;}app.status='Shortlisted, interview to schedule';app.nextText='Schedule the first interview';app.next='13 Sep 2026';app.nextOwner=recUser();recLog(app,'Screening completed: '+s.rec);recMove(app,'Shortlisted');render();showToast('Shortlisted. Screening checklist complete and recommendation recorded.');break;}
 case 'rec-schedule':if(!app)break;dialog('Schedule interview / '+esc(candOf(app).name),`<form id="rec-int-form" novalidate><div class="form-grid"><label>Interview ID<input value="${recNextId('INT')}" readonly name="intId"></label><label>Round ${sel('rec-i-round',['Round 1','Round 2','Round 3','Final'],'Round '+(app.interviews.length+1),'name="round"')}</label><label>Interview type ${sel('rec-i-type',['Screening','HR','Functional','Manager','Final','Other'],'','name="type"')}</label><label>Interview mode ${sel('rec-i-mode',['In-person','Video','Phone'],'','name="mode"')}</label><label>Date<input name="date" type="date" value="2026-09-15"></label><label>Time<input name="time" type="time" value="11:00"></label><label class="full">Location / link<input name="where" placeholder="Meeting room or video link"></label><label class="full">Interviewer(s) <span aria-hidden="true">*</span><input name="interviewers" placeholder="One or more names"></label><label>Candidate confirmation ${sel('rec-i-confirm',['Pending','Confirmed','Declined'],'Pending','name="confirm"')}</label><label>Reminder<input value="Automated, 1 day before" readonly></label></div><p id="rec-int-error" class="error" role="alert"></p><button class="primary">Schedule</button></form>`);break;
 case 'rec-int-complete':{const i=app&&app.interviews.find(x=>x.id===id);if(!i)break;i.status='Completed';recLog(app,'Interview '+i.id+' completed. Feedback pending from '+i.interviewers+'.');if(app.interviews.every(x=>x.status!=='Scheduled')){app.status='Feedback pending';app.nextText='Submit interview feedback';app.nextOwner=i.interviewers;recMove(app,'Interview Completed');}render();showToast('Marked completed. Structured feedback is now required.');break;}
 case 'rec-int-resched':{const i=app&&app.interviews.find(x=>x.id===id);if(!i)break;dialog('Reschedule '+i.id,`<form id="rec-resched-form" data-int="${i.id}" novalidate><div class="form-grid"><label>New date<input name="date" type="date" value="2026-09-16"></label><label>New time<input name="time" type="time" value="11:00"></label></div><label class="spacer">Reschedule reason <span aria-hidden="true">*</span><textarea name="reason"></textarea></label><p id="rec-resched-error" class="error" role="alert"></p><button class="primary">Reschedule</button></form>`);break;}
 case 'rec-int-feedback':{const [appId,intId]=String(id).split('|');const ap=appOf(appId),i=ap&&ap.interviews.find(x=>x.id===intId);if(!i)break;state.rec.app=appId;dialog('Interview feedback / '+esc(candOf(ap).name),recFeedbackForm(ap,i));break;}
 case 'rec-int-view':{const [appId,intId]=String(id).split('|');const ap=appOf(appId),i=ap&&ap.interviews.find(x=>x.id===intId);if(!i||!i.feedback)break;const f=i.feedback,j=jobOf(ap);const rows=[...REC_FB_COMMON,...(REC_FB_ROLE[j.role]||[]),...REC_FB_TAIL];dialog(i.id+' / '+i.round+' feedback',`<p class="subtle">${esc(i.interviewers)}, ${i.when}</p>${rows.map(([k,l])=>kv(l,(f[k]||'-')+' / 5')).join('')}${kv('Strengths',esc(f.strengths))+kv('Concerns / gaps',esc(f.concerns||'None'))+kv('Final recommendation',esc(f.rec))+kv('Remarks',esc(f.remarks))+kv('Recorded by',esc(f.by)+', '+f.on)}`);break;}
 case 'rec-eval':if(app&&app.stage==='Interview Completed'){if(!feedbackDone(app)){showToast('Move blocked: feedback is pending for a completed round.');break;}app.status='Ready for selection';app.nextText='Record the final selection';app.nextOwner='Kavita Demo';recMove(app,'Final Evaluation','All mandatory feedback received.');render();showToast('Moved to final evaluation.');}break;
 case 'rec-select':if(!app||app.stage!=='Final Evaluation')break;{const j=jobOf(app),c=candOf(app),last=app.interviews.filter(i=>i.feedback).slice(-1)[0];dialog('Final selection / '+esc(c.name),`<form id="rec-sel-form" novalidate>${kv('Final interview completed','Yes')+kv('All mandatory feedback received','Yes')}<div class="form-grid spacer"><label>Final recommendation ${sel('rec-f-rec',['Strong Hire','Hire','Hold','Reject'],last?last.feedback.rec:'','name="finalRec"')}</label><label>Decision ${sel('rec-f-dec',['Selected','Rejected','Hold'],'','name="decision"')}</label><label>Selected role ${sel('rec-f-role',['RM','Operations'],j.role,'name="role"')}</label><label>Selected designation<input name="designation" value="${esc(j.title)}"></label><label>Reporting manager<input name="manager" value="${j.role==='RM'?'Kavita Demo':'Nikhil Demo'}"></label><label>Work location<input name="location" value="${esc(j.location)}"></label><label>Proposed joining date<input name="joining" type="date" value="2026-10-15"></label><label>Approved CTC<input name="ctc" value="${esc(c.ectc)}"></label><label>Incentive / variable pay<input name="incentive" value="${j.role==='RM'?'Quarterly, on net sales':'Not applicable'}"></label><label>Probation period<input name="probation" value="6 months"></label><label>Notice period<input name="notice" value="30 days"></label><label>Final approver<input value="Kavita Demo" readonly></label><label class="full">Selection remarks <span aria-hidden="true">*</span><textarea name="remarks"></textarea></label></div><p id="rec-sel-error" class="error" role="alert"></p><button class="primary">Record selection</button></form>`);break;}
 case 'rec-approve-comp':if(app&&recRole()==='senior'&&app.approval===2){app.approval=3;app.nextText='Give final approval';recLog(app,'Compensation approved: '+app.selection.ctc+' by '+recUser());render();showToast('Compensation approved.');}break;
 case 'rec-approve-final':if(app&&recRole()==='senior'&&app.approval===3){app.approval=4;app.selection.on=REC_TODAY;app.status='Approved, offer to prepare';app.nextText='Prepare and release the offer';app.nextOwner='Meera Demo';recLog(app,'Final approval given by '+recUser()+'. Offer preparation can start.');render();showToast('Final approval recorded. HR can now prepare the offer.');}break;
 case 'rec-offer':if(!app||app.approval<4||app.offer)break;{const s=app.selection;dialog('Prepare offer / '+esc(candOf(app).name),`<form id="rec-offer-form" novalidate><div class="form-grid"><label>Offer ID<input name="offerId" value="${recNextId('OFR')}" readonly></label><label>Offer date<input name="date" type="date" value="2026-09-12"></label><label>Role / designation<input name="role" value="${esc(s.designation)}"></label><label>Department<input name="dept" value="${esc(jobOf(app).dept)}"></label><label>Reporting manager<input name="manager" value="${esc(s.manager)}"></label><label>Location<input name="location" value="${esc(s.location)}"></label><label>Joining date<input name="joining" value="${esc(s.joining)}"></label><label>CTC<input name="ctc" value="${esc(s.ctc)}"></label><label>Fixed pay<input name="fixed" placeholder="Break-up if required"></label><label>Variable / incentive<input name="variable" value="${esc(s.incentive)}"></label><label>Probation<input name="probation" value="${esc(s.probation)}"></label><label>Notice period<input name="notice" value="${esc(s.notice)}"></label><label class="full">Offer letter<input value="Generated from the approved template on release" readonly></label></div><p id="rec-offer-error" class="error" role="alert"></p><button class="primary">Release offer</button></form>`);break;}
 case 'rec-offer-accept':if(!app||!app.offer||app.offer.status!=='Released')break;dialog('Record offer acceptance',`<form id="rec-accept-form" novalidate><div class="form-grid"><label>Acceptance date<input name="on" type="date" value="2026-09-12"></label><label>Joining date<input name="joining" value="${esc(app.offer.joining)}"></label><label class="full">Signed offer / acceptance<input type="file" disabled><small class="muted">No file is uploaded in this preview.</small></label><label class="full">Candidate remarks<textarea name="remarks"></textarea></label></div><p id="rec-accept-error" class="error" role="alert"></p><button class="primary">Record acceptance</button></form>`);break;
 case 'rec-offer-decline':if(app&&app.offer)recReasonDialog('decline','Offer declined','Decline reason, if provided by the candidate.');break;
 case 'rec-offer-withdraw':if(app&&app.offer)recReasonDialog('withdraw-offer','Withdraw offer','Withdrawal reason. The offer record is retained.');break;
 case 'rec-prejoin-start':if(app&&app.stage==='Offer Accepted'){app.prejoin=prejoin([0]);app.status='0 of 9 checklist items done';app.nextText='Documents requested';app.nextOwner='Meera Demo';recMove(app,'Pre-Joining','Checklist owners assigned.');render();showToast('Pre-joining started. Each checklist task has an owner.');}break;
 case 'rec-prejoin-tick':if(app&&app.prejoin&&app.stage==='Pre-Joining'){const t=app.prejoin[Number(id)];if(t.task==='Joining confirmation'){render();showToast('Joining confirmation is recorded through Mark joined.');break;}t.done=!t.done;app.status=app.prejoin.filter(x=>x.done).length+' of 9 checklist items done';recLog(app,'Pre-joining: '+t.task+(t.done?' done':' reopened'));render();}break;
 case 'rec-joined':if(app&&app.stage==='Pre-Joining'){if(!prejoinReady(app)){showToast('Move blocked: complete the mandatory pre-joining items first.');break;}dialog('Joining confirmation',`<form id="rec-join-form" novalidate><div class="form-grid"><label>Joining date<input name="on" type="date" value="2026-09-15"></label><label>Confirmed by<input value="${recUser()}" readonly></label></div><p class="subtle spacer">Confirms the candidate reported on the joining date. Conversion to employee is a separate, controlled action.</p><button class="primary spacer">Confirm joining</button></form>`);}break;
 case 'rec-convert':if(app&&app.stage==='Joined'&&recRole()==='hr'){const c=candOf(app),s=app.selection;dialog('Convert to employee / '+esc(c.name),`<p class="subtle">The following is transferred into the employee master. The application remains as recruitment history.</p>${kv('Candidate / application',c.id+' / '+app.id)+kv('Name and contact',esc(c.name)+', '+esc(c.mobile)+', '+esc(c.email))+kv('Role and designation',esc(s.role)+', '+esc(s.designation))+kv('Department',esc(jobOf(app).dept))+kv('Reporting manager',esc(s.manager))+kv('Work location',esc(s.location))+kv('Date of joining',esc(app.joinedOn))+kv('Approved compensation',pay(s.ctc)+(recCanPay()?', '+esc(s.incentive):''))+kv('Offer and acceptance',app.offer.id+', accepted '+app.offer.acceptedOn)+kv('Verified documents',recDocsFor(c.id).filter(d=>d.status==='Verified').length+' documents')+kv('Interview and selection history',app.interviews.length+' rounds, final recommendation '+esc(s.finalRec))+kv('Recruitment source',esc(c.source)+', '+esc(c.sourceDetail))+kv('Employee code','Next free code, assigned by HR')}<div class="actions spacer">${btn('Create employee record','rec-convert-confirm',true)}</div>`);}break;
 case 'rec-convert-confirm':if(app&&app.stage==='Joined'){app.converted=REC_TODAY;app.employeeCode='ACN-025';app.status='Converted to employee';app.next='';app.nextText='';recMove(app,'Converted','Employee '+app.employeeCode+' created.');closeDialog();render();showToast('Employee record created in this preview. The recruitment record is retained.');}break;
 case 'rec-reject':if(app&&!app.outcome)recReasonDialog('reject','Reject candidate','Rejection reason and remarks are mandatory and stay on the record.');break;
 case 'rec-hold':if(app&&!app.outcome)recReasonDialog('hold','Put on hold','Reason and the next review date are mandatory.','<label class="spacer">Next review / follow-up date<input name="review" type="date" value="2026-09-30"></label>');break;
 case 'rec-withdraw':if(app&&!app.outcome)recReasonDialog('withdraw','Candidate withdrew','Withdrawal reason and date.');break;
 case 'rec-defer':if(app&&!app.outcome)recReasonDialog('defer','Joining deferred','Reason and the new expected joining date.','<label class="spacer">New expected joining date<input name="review" type="date" value="2026-10-01"></label>');break;
 case 'rec-doc-verify':{const [cid,name]=String(id).split('|');const d=recDocsFor(cid).find(x=>x.name===name);if(d&&recRole()==='hr'){d.status='Verified';d.by=recUser();d.on=REC_TODAY;render();showToast(name+' verified. Verification date and verifier recorded.');}break;}
 }
}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action^="rec-"]');if(t&&!t.disabled)recAction(t.dataset.action,t.dataset.id);});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='rec-source'){state.rec.source=e.target.value;render();}if(id==='rec-stage'){state.rec.stageF=e.target.value;render();}if(id==='rec-jobfilter'){state.rec.jobFilter=e.target.value.split(' ')[0];render();}if(id==='rec-ownerfilter'){state.rec.ownerFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='rec-search'){state.rec.search=e.target.value;const pos=e.target.selectionStart;render();const box=$('#rec-search');if(box){box.focus();box.setSelectionRange(pos,pos);}}});
document.addEventListener('submit',e=>{const form=e.target,fid=form.getAttribute('id')||'';if(!fid.startsWith('rec-'))return;e.preventDefault();const d=Object.fromEntries(new FormData(form));const app=appOf(state.rec.app);
 if(fid==='rec-req-form'){if(!d.role||!d.dept||!d.reason||!d.manager.trim()||!d.location||!d.exp.trim()||!d.skills.trim()||!d.budget.trim()||!d.target||!d.priority||!d.jd.trim()){$('#rec-req-error').textContent='Every field except remarks is mandatory.';return;}recReqs.push({id:'MR-0014',by:recUser(),role:d.role,dept:d.dept,positions:Number(d.positions)||1,reason:d.reason,manager:d.manager,location:d.location,type:d.type,exp:d.exp,skills:d.skills,budget:d.budget,target:recDate(d.target),priority:d.priority,jd:d.jd,status:'Pending',approver:'',on:'',remarks:d.remarks});closeDialog();location.hash='openings';render();showToast('MR-0014 submitted for approval. No job opening exists until it is approved.');}
 if(fid==='rec-reason-form'){const kind=form.dataset.kind;if(!d.reason.trim()){$('#rec-reason-error').textContent='A reason is mandatory.';return;}if(kind.startsWith('req:')){const r=recReqs.find(x=>x.id===kind.slice(4));r.status='Rejected';r.approver=recUser();r.on=REC_TODAY;r.remarks=d.reason;closeDialog();render();showToast(r.id+' rejected with a recorded reason.');return;}if(!app)return;const map={reject:'Rejected',hold:'On Hold',withdraw:'Candidate Withdrawn',decline:'Offer Declined','withdraw-offer':'Offer Withdrawn',defer:'Joining Deferred'};if(kind==='decline'||kind==='withdraw-offer')app.offer.status=kind==='decline'?'Declined':'Withdrawn';recSetOutcome(app,map[kind],d.reason.trim(),d.review?recDate(d.review):'');closeDialog();render();showToast(map[kind]+' recorded with the reason on the timeline.');}
 if(fid==='rec-cand-form'){const existing=form.dataset.existing;if(!d.job){$('#rec-cand-error').textContent='Choose the job opening.';return;}const jobId=d.job.split(' ')[0];let c=existing?recCandidates.find(x=>x.id===existing):null;if(!c){const digits=(d.mobile||'').replace(/\D/g,'');if(!d.first.trim()||!d.last.trim()||digits.length<10||!d.email.trim()||!d.city.trim()||!d.source||!d.exp.trim()||!d.relExp.trim()||!d.ectc.trim()||!d.notice.trim()||!d.skills.trim()){$('#rec-cand-error').textContent='Fill every mandatory field (marked *). Mobile must have 10 digits.';return;}const dup=recCandidates.find(x=>x.mobile.replace(/\D/g,'')===digits||x.email.toLowerCase()===d.email.trim().toLowerCase()||x.name.toLowerCase()===(d.first.trim()+' '+d.last.trim()).toLowerCase());if(dup&&!form.dataset.dupSeen){form.dataset.dupSeen=dup.id;$('#rec-dup').innerHTML=notice('Possible duplicate: '+esc(dup.name)+' ('+dup.id+')','Same mobile number, email or name as an existing candidate. Open the existing record and add a new application instead of creating a second candidate. '+recApps.filter(x=>x.cand===dup.id).length+' application(s) already linked.','amber')+`<div class="actions">${btn('Open existing candidate','rec-cand',true,`data-id="${dup.id}"`)}${btn('Add application to the existing candidate','rec-add-app',false,`data-id="${dup.id}"`)}</div><p class="subtle spacer">Submitting again creates a new candidate anyway and writes the override to the timeline. Whether an override should be allowed at all is a question for you.</p>`;$('#rec-cand-error').textContent='';return;}const initials=(d.first[0]+d.last[0]).toUpperCase();c={id:'CND-0'+(228+recCandidates.filter(x=>Number(x.id.slice(4))>=228).length),name:[d.first,d.middle,d.last].filter(x=>x&&x.trim()).join(' '),initials,color:'',mobile:digits.slice(0,5)+' '+digits.slice(5,10),alt:d.alt,email:d.email.trim(),gender:'',city:d.city,address:d.address,permanent:'',pref:d.pref,linkedin:d.linkedin,source:d.source,sourceDetail:d.sourceDetail,company:d.company,designation:d.designation,exp:d.exp,relExp:d.relExp,ctc:'',ectc:d.ectc,notice:d.notice,joinBy:'',reason:'',skills:d.skills.split(',').map(x=>x.trim()).filter(Boolean),certs:'',industry:'',resume:d.last.trim()+'_CV.pdf'};recCandidates.push(c);}
  const id=recNextId('APP');recApps.push({id,cand:c.id,job:jobId,date:REC_TODAY,source:d.asource||c.source,owner:'Meera Demo',stage:'New Application',status:'Awaiting screening',priority:d.priority||'Medium',next:'13 Sep 2026',nextOwner:'Meera Demo',nextText:'Start screening',notes:'',screening:null,interviews:[],selection:null,approval:0,offer:null,prejoin:null,outcome:null,timeline:[ev(recNow(),'Application received ('+(d.asource||c.source)+')'+(existing?'. Linked to existing candidate '+c.id+'; no second candidate record created.':form.dataset.dupSeen?'. Candidate created despite a possible duplicate ('+form.dataset.dupSeen+'); override recorded.':'. Candidate '+c.id+' created; no duplicate found for the mobile number, email or name.'),recUser())]});closeDialog();state.rec.app=id;location.hash='application';render();showToast((existing?'Application ':'Candidate and application ')+id+' created against '+jobId+'.');}
 if(fid==='rec-int-form'){if(!app)return;if(!d.round||!d.type||!d.mode||!d.date||!d.time||!d.interviewers.trim()||(d.mode!=='Phone'&&!d.where.trim())){$('#rec-int-error').textContent='Round, type, mode, date, time, interviewers and a location or link are mandatory.';return;}const when=recDate(d.date)+', '+d.time;app.interviews.push({id:d.intId,round:d.round,type:d.type,mode:d.mode,when,where:d.where,interviewers:d.interviewers.trim(),confirm:d.confirm||'Pending',status:'Scheduled',feedback:null});app.status=d.round+' on '+recDate(d.date);app.next=recDate(d.date);app.nextText=d.round+', '+d.type.toLowerCase()+' interview';app.nextOwner=d.interviewers.trim();recLog(app,'Interview '+d.intId+' scheduled: '+d.round+', '+d.type+', '+when+' ('+d.mode.toLowerCase()+'). Reminder automated.');if(app.stage!=='Interview Scheduled')recMove(app,'Interview Scheduled');closeDialog();render();showToast('Interview scheduled. A reminder goes out one day before.');}
 if(fid==='rec-resched-form'){const i=app&&app.interviews.find(x=>x.id===form.dataset.int);if(!i)return;if(!d.reason.trim()||!d.date){$('#rec-resched-error').textContent='A reschedule reason and new date are mandatory.';return;}const old=i.when;i.when=recDate(d.date)+', '+d.time;i.status='Scheduled';i.confirm='Pending';app.next=recDate(d.date);recLog(app,'Interview '+i.id+' rescheduled from '+old+' to '+i.when+'. Reason: '+d.reason.trim());closeDialog();render();showToast('Rescheduled. Reason kept on the timeline; candidate confirmation reset to pending.');}
 if(fid==='rec-fb-form'){const ap=appOf(form.dataset.app),i=ap&&ap.interviews.find(x=>x.id===form.dataset.int);if(!i)return;const j=jobOf(ap),rows=[...REC_FB_COMMON,...(REC_FB_ROLE[j.role]||[]),...REC_FB_TAIL];if(rows.some(([k])=>!d[k])||!d.strengths.trim()||!d.rec||!d.remarks.trim()){$('#rec-fb-error').textContent='Rate every row and fill strengths, final recommendation and remarks.';return;}i.feedback={...d,by:recUser(),on:REC_TODAY};recLog(ap,'Interview '+i.id+' feedback recorded: '+d.rec+' (overall '+d.overall+' / 5)');if(feedbackDone(ap)&&ap.stage==='Interview Completed'){ap.status='Feedback complete';ap.nextText=d.rec==='Further Round'?'Schedule a further round':'Move to final evaluation';ap.nextOwner='Meera Demo';}closeDialog();render();showToast('Feedback submitted. '+(feedbackDone(ap)?'All rounds now have feedback.':'Another round still needs feedback.'));}
 if(fid==='rec-sel-form'){if(!app)return;if(!d.finalRec||!d.decision||!d.role||!d.designation.trim()||!d.manager.trim()||!d.location.trim()||!d.joining||!d.ctc.trim()||!d.probation.trim()||!d.notice.trim()||!d.remarks.trim()){$('#rec-sel-error').textContent='Every selection field is mandatory.';return;}if(d.decision!=='Selected'){closeDialog();recReasonDialog(d.decision==='Hold'?'hold':'reject',d.decision==='Hold'?'Put on hold':'Reject candidate','Recorded from the final evaluation.',d.decision==='Hold'?'<label class="spacer">Next review date<input name="review" type="date" value="2026-09-30"></label>':'');return;}app.selection={finalRec:d.finalRec,decision:d.decision,role:d.role,designation:d.designation,manager:d.manager,location:d.location,joining:recDate(d.joining),ctc:d.ctc,incentive:d.incentive,probation:d.probation,notice:d.notice,remarks:d.remarks,approver:'Kavita Demo',on:''};app.approval=2;app.status='Compensation approval pending';app.nextText='Approve compensation';app.nextOwner='Kavita Demo';recLog(app,'Final selection recorded: Selected, '+d.designation+', '+d.ctc+', joining '+recDate(d.joining));recMove(app,'Selected','Compensation approval pending.');closeDialog();render();showToast('Selected. No offer can be released until compensation and final approval are recorded.');}
 if(fid==='rec-offer-form'){if(!app)return;if(!d.role.trim()||!d.manager.trim()||!d.joining.trim()||!d.ctc.trim()||!d.probation.trim()||!d.notice.trim()){$('#rec-offer-error').textContent='Role, manager, joining date, CTC, probation and notice period are mandatory.';return;}app.offer={id:d.offerId,date:recDate(d.date),role:d.role,dept:d.dept,manager:d.manager,location:d.location,joining:d.joining,ctc:d.ctc,fixed:d.fixed||'Not broken up',variable:d.variable,probation:d.probation,notice:d.notice,letter:'Offer_Letter_'+d.offerId+'.pdf',status:'Released',acceptedOn:'',remarks:''};app.status='Awaiting candidate response';app.nextText='Follow up on the offer';app.next='15 Sep 2026';app.nextOwner='Meera Demo';recLog(app,'Offer '+d.offerId+' released: '+d.ctc+', joining '+d.joining+'. Offer letter generated.');recMove(app,'Offer Released');closeDialog();render();showToast('Offer released and recorded. Nothing is emailed from this preview.');}
 if(fid==='rec-accept-form'){if(!app||!app.offer)return;app.offer.status='Accepted';app.offer.acceptedOn=recDate(d.on);app.offer.joining=d.joining;app.offer.remarks=d.remarks;app.status='Offer accepted';app.nextText='Start pre-joining';app.next=REC_TODAY;app.nextOwner='Meera Demo';recLog(app,'Offer accepted on '+recDate(d.on)+'; joining '+d.joining+'. Pre-joining checklist opened automatically.');recMove(app,'Offer Accepted');closeDialog();render();showToast('Acceptance recorded. The pre-joining checklist is open.');}
 if(fid==='rec-join-form'){if(!app||!prejoinReady(app))return;app.prejoin.find(t=>t.task==='Joining confirmation').done=true;app.joinedOn=recDate(d.on);app.status='Joined '+app.joinedOn+'; conversion pending';app.nextText='Convert to employee';app.next=REC_TODAY;app.nextOwner='Meera Demo';recLog(app,'Joining confirmed by '+recUser()+' on '+app.joinedOn);recMove(app,'Joined');closeDialog();render();showToast('Joined. Convert to employee when ready.');}
});
render();
